import{_ as t,o as a,c as o,ag as r}from"./chunks/framework.CU0NaXTj.js";const M=JSON.parse('{"title":"MVVM模式","description":"","frontmatter":{"title":"MVVM模式","date":"2020-02-04T12:19:00.000Z","permalink":"/pages/114158caa9e96df0","categories":["《Vue》笔记","基础"],"tags":["Vue"],"author":{"name":"dazaer007","link":"https://github.com/xugaoyi"}},"headers":[],"relativePath":"《Vue》笔记/01.基础/00.MVVM模式.md","filePath":"《Vue》笔记/01.基础/00.MVVM模式.md","lastUpdated":1774415064000}'),s={name:"《Vue》笔记/01.基础/00.MVVM模式.md"};function i(p,e,V,c,d,n){return a(),o("div",null,[...e[0]||(e[0]=[r('<div class="tip custom-block"><p class="custom-block-title">TIP</p><p>说明：本章内容是博主的Vue学习笔记，以<a href="https://cn.vuejs.org/v2/guide/" target="_blank" rel="noreferrer">官方文档</a>为准。</p></div><h1 id="mvvm模式" tabindex="-1">MVVM模式 <a class="header-anchor" href="#mvvm模式" aria-label="Permalink to &quot;MVVM模式&quot;">​</a></h1><p>MVVM模式，<code>M</code>即 model，数据模型；<code>V</code>即 view，视图；<code>VM</code>即 view-model，视图模型。</p><p><img src="https://cdn.staticaly.com/gh/xugaoyi/image_store/blog/20200204123438.png" alt=""></p><p><strong>理解</strong></p><p>首先，数据Model通过Data Bindings把数据绑定在View视图上，</p><p>当View视图有交互（有改变）的时候，Dom listeners会自动监听，然后更新数据Model。</p><p><strong>Q：什么是MVVM模式？</strong></p><p>A：MVVM模式，第一个M代表数据模型，V代表视图，VM代表视图模型； 它的实际操作原理是：后台数据通过视图模型来渲染视图，就是页面。当用户在页面上进行操作的时候， 视图模型会自动监听到用户的操作，从而改变后台数据。</p>',9)])])}const _=t(s,[["render",i]]);export{M as __pageData,_ as default};
